    topic: 'gm_networks', year_level: 'year_12', difficulty: 'proficient',
    format: 'extended_response',
    calculator_allowed: true,
    diagram: {"kind":"network_graph","title":"Cost of laying pipe between sites ($000)","vertices":[{"id":"P","x":8,"y":82},{"id":"Q","x":40,"y":96},{"id":"R","x":36,"y":50},{"id":"S","x":70,"y":78},{"id":"T","x":68,"y":26},{"id":"U","x":95,"y":48}],"edges":[{"from":"P","to":"Q","weight":7},{"from":"P","to":"R","weight":4},{"from":"Q","to":"R","weight":3},{"from":"Q","to":"S","weight":6},{"from":"R","to":"T","weight":8},{"from":"S","to":"T","weight":5},{"from":"S","to":"U","weight":9},{"from":"T","to":"U","weight":2}]},
