    diagram: {"kind":"drawing","width":340,"height":80,"elements":[{"t":"line","x1":20,"y1":30,"x2":20,"y2":70,"w":1.2},{"t":"line","x1":20,"y1":34,"x2":14,"y2":39,"grey":true,"w":0.7},{"t":"line","x1":20,"y1":42,"x2":14,"y2":47,"grey":true,"w":0.7},{"t":"line","x1":20,"y1":50,"x2":14,"y2":55,"grey":true,"w":0.7},{"t":"line","x1":20,"y1":58,"x2":14,"y2":63,"grey":true,"w":0.7},{"t":"line","x1":20,"y1":66,"x2":14,"y2":71,"grey":true,"w":0.7},{"t":"poly","points":[[20,70],[23.5,70],[27,70],[30.5,70],[34,70],[37.5,70],[41,70],[44.5,70],[48,70],[51.5,70],[55,70],[58.5,70],[62,70],[65.5,70],[69,70],[72.5,70],[76,70],[79.5,70],[83,70],[86.5,70],[90,70],[93.5,70],[97,70],[100.5,70],[104,70],[107.5,70],[111,70],[114.5,70],[118,70],[121.5,70],[125,70],[128.5,70],[132,70],[135.5,70],[139,70],[142.5,70],[146,70],[149.5,70],[153,69.77],[156.5,68.94],[160,67.52],[163.5,65.55],[167,63.07],[170.5,60.14],[174,56.85],[177.5,53.26],[181,49.46],[184.5,45.56],[188,41.64],[191.5,37.81],[195,34.15],[198.5,30.76],[202,27.72],[205.5,25.11],[209,22.99],[212.5,21.4],[216,20.4],[219.5,20.01],[223,20.23],[226.5,21.06],[230,22.48],[233.5,24.45],[237,26.93],[240.5,29.86],[244,33.15],[247.5,36.74],[251,40.54],[254.5,44.44],[258,48.36],[261.5,52.19],[265,55.85],[268.5,59.24],[272,62.28],[275.5,64.89],[279,67.01],[282.5,68.6],[286,69.6],[289.5,69.99],[293,70],[296.5,70],[300,70]],"w":1.3},{"t":"poly","points":[[20,59],[25.52,59],[28.43,64],[31.35,54],[34.26,64],[37.17,54],[40.09,64],[43,54],[45.91,64],[48.83,54],[51.74,64],[54.65,54],[57.57,64],[60.48,59],[66,59]]},{"fill":"light","t":"rect","x":66,"y":48,"w":34,"h":22},{"t":"text","x":83,"y":62,"text":"2.0 kg","size":8},{"t":"line","x1":220,"y1":20,"x2":306,"y2":20,"dash":true,"grey":true},{"t":"line","x1":306,"y1":20,"x2":306,"y2":70,"arrow":"both","w":0.8},{"t":"text","x":324,"y":48,"text":"0.60 m","size":9}],"caption":"Figure 4"},
    question_text: "A spring with a spring constant of 800 N m⁻¹ is compressed by 0.20 m and used to launch a 2.0 kg cart along a track. The track then rises over a hill 0.60 m high, as shown in Figure 4. Ignore friction and air resistance.",
    parts: [
      { label: "a", prompt: "Calculate the elastic potential energy stored in the compressed spring.", marks: 1, expected_answer: "16 J", explanation: "\\(E_s = \\frac{1}{2}kx^2 = \\frac{1}{2} \\times 800 \\times 0.20^2 = 16\\) J.", lines: 2, unit: "J" },
      { label: "b", prompt: "Calculate the speed of the cart as it leaves the spring.", marks: 1, expected_answer: "4.0 m s⁻¹", explanation: "\\(\\frac{1}{2}mv^2 = 16\\), so \\(v = \\sqrt{\\frac{2 \\times 16}{2.0}} = 4.0\\) m s⁻¹.", lines: 2, unit: "m s⁻¹" },
      { label: "c", prompt: "Calculate the speed of the cart at the top of the hill.", marks: 2, expected_answer: "2.06 m s⁻¹", explanation: "\\(E_k = 16 - mgh = 16 - 2.0 \\times 9.81 \\times 0.60 = 4.23\\) J, so \\(v = \\sqrt{\\frac{2 \\times 4.23}{2.0}} = 2.06\\) m s⁻¹. 1 mark for the energy remaining, 1 mark for the speed.", lines: 4, unit: "m s⁻¹" },
      { label: "d", prompt: "Calculate the height of the highest hill the cart could get over.", marks: 1, expected_answer: "0.82 m", explanation: "All 16 J becomes gravitational potential energy: \\(h = \\frac{16}{2.0 \\times 9.81} = 0.82\\) m (strictly, just under this, so that the cart is still moving at the top).", lines: 2, unit: "m" },
      { label: "e", prompt: "Describe the energy transformations from the moment the cart is released until it reaches the top of the hill.", marks: 1, expected_answer: "Elastic potential energy → kinetic energy (as the spring extends) → partly gravitational potential energy as the cart climbs, with the rest remaining as kinetic energy.", explanation: "All three forms, in order, are needed for the mark.", lines: 3 },
    ],
